#[test]
fn parity_batch_response_text() {
    for case in cases(&load("format.json"), "batchResponseText") {
        let input = case.get("input").expect("input");
        let upstream = input.get("result").expect("result");
        let mut items = Vec::new();
        for item in upstream
            .get("items")
            .and_then(Value::as_array)
            .unwrap_or(&Vec::new())
        {
            items.push(BatchFetchItemResult {
                index: item
                    .get("index")
                    .and_then(Value::as_u64)
                    .unwrap_or_default() as usize,
                request_url: item
                    .get("request")
                    .and_then(|r| r.get("url"))
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string(),
                status: if item.get("status").and_then(Value::as_str) == Some("error") {
                    "error"
                } else {
                    "done"
                },
                error: item
                    .get("error")
                    .and_then(Value::as_str)
                    .map(str::to_string),
                result: item.get("result").map(|result| {
                    serde_json::from_value(result.clone()).expect("FetchResult replays")
                }),
            });
        }
        let batch = BatchFetchResult {
            items,
            total: upstream
                .get("total")
                .and_then(Value::as_u64)
                .unwrap_or_default(),
            succeeded: upstream
                .get("succeeded")
                .and_then(Value::as_u64)
                .unwrap_or_default(),
            failed: upstream
                .get("failed")
                .and_then(Value::as_u64)
                .unwrap_or_default(),
            batch_concurrency: upstream
                .get("batchConcurrency")
                .and_then(Value::as_u64)
                .unwrap_or_default(),
        };
        let verbose = input
            .get("verbose")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        assert_eq!(
            batch::build_batch_fetch_response_text(&batch, verbose),
            str_field(&case, "output"),
            "case {}",
            str_field(&case, "name")
        );
    }
}

